"""Tokenizer for the microvm language."""

import dataclasses

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)

_ESCAPES: dict[str, str] = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}

# Longest match wins: two-character operators first.
_OPS: tuple[str, ...] = (
    "==", "!=", "<=", ">=", "+", "-", "*", "/", "%", "(", ")", "{", "}", ";", "=", "<", ">",
)


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str      # "INT" | "FLOAT" | "STRING" | "IDENT" | "KEYWORD" | "OP"
    text: str      # the source lexeme (for STRING: the decoded value)
    value: object  # INT -> int, FLOAT -> float, STRING -> decoded str, else same as text
    offset: int    # zero-based character offset of the first character


def _read_number(src: str, start: int) -> tuple[Token, int]:
    """Read an integer or float literal starting at ``start``."""
    n = len(src)
    i = start
    while i < n and src[i].isdigit():
        i += 1
    is_float = False
    if i < n and src[i] == ".":
        is_float = True
        i += 1
        if i >= n or not src[i].isdigit():
            raise LexError("expected digit after '.'", i if i < n else n)
        while i < n and src[i].isdigit():
            i += 1
    if i < n and src[i] in "eE":
        is_float = True
        i += 1
        if i < n and src[i] in "+-":
            i += 1
        if i >= n or not src[i].isdigit():
            raise LexError("expected digit in exponent", i)
        while i < n and src[i].isdigit():
            i += 1
    text = src[start:i]
    if is_float:
        return Token("FLOAT", text, float(text), start), i
    return Token("INT", text, int(text), start), i


def _read_string(src: str, start: int) -> tuple[Token, int]:
    """Read a double-quoted string literal starting at ``start``."""
    parts: list[str] = []
    i = start + 1
    n = len(src)
    while i < n:
        ch = src[i]
        if ch == '"':
            value = "".join(parts)
            return Token("STRING", value, value, start), i + 1
        if ch == "\n":
            raise LexError("literal newline in string", i)
        if ch == "\\":
            if i + 1 >= n or src[i + 1] not in _ESCAPES:
                raise LexError("invalid escape sequence", i)
            parts.append(_ESCAPES[src[i + 1]])
            i += 2
        else:
            parts.append(ch)
            i += 1
    raise LexError("unterminated string", start)


def _read_ident(src: str, start: int) -> tuple[Token, int]:
    """Read an identifier or keyword starting at ``start``."""
    i = start
    n = len(src)
    while i < n and (src[i].isalnum() or src[i] == "_"):
        i += 1
    text = src[start:i]
    if text in KEYWORDS:
        return Token("KEYWORD", text, text, start), i
    return Token("IDENT", text, text, start), i


def tokenize(src: str) -> list[Token]:
    """Split ``src`` into tokens; raise ``LexError`` on malformed input."""
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if src.startswith("//", i):
            j = src.find("\n", i)
            i = n if j == -1 else j + 1
            continue
        if ch.isdigit():
            tok, i = _read_number(src, i)
        elif ch == '"':
            tok, i = _read_string(src, i)
        elif ch.isalpha() or ch == "_":
            tok, i = _read_ident(src, i)
        else:
            tok = None
            for op in _OPS:
                if src.startswith(op, i):
                    tok = Token("OP", op, op, i)
                    i += len(op)
                    break
            if tok is None:
                raise LexError(f"unexpected character {ch!r}", i)
        tokens.append(tok)
    return tokens

"""Recursive-descent parser producing an untyped AST of dataclass nodes."""

import dataclasses

from .errors import ParseError
from .lexer import Token, tokenize

# ---------------------------------------------------------------------------
# AST nodes (representation is internal; only error behaviour is observable).


@dataclasses.dataclass
class Literal:
    value: object
    offset: int


@dataclasses.dataclass
class Var:
    name: str
    offset: int


@dataclasses.dataclass
class BinOp:
    op: str
    left: object
    right: object
    offset: int


@dataclasses.dataclass
class UnaryOp:
    op: str          # "-" or "not"
    operand: object
    offset: int


@dataclasses.dataclass
class Let:
    name: str
    value: object
    offset: int


@dataclasses.dataclass
class Assign:
    name: str
    value: object
    offset: int


@dataclasses.dataclass
class Print:
    value: object
    offset: int


@dataclasses.dataclass
class If:
    cond: object
    then: list
    otherwise: list  # empty when there is no else
    offset: int


@dataclasses.dataclass
class While:
    cond: object
    body: list
    offset: int


_COMPARISONS = ("==", "!=", "<", "<=", ">", ">=")


class _Parser:
    """Token cursor with precedence-climbing expression parsing."""

    def __init__(self, src: str) -> None:
        self.tokens = tokenize(src)
        self.pos = 0
        self.end = len(src)

    def _peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _advance(self) -> Token:
        tok = self._peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.end)
        self.pos += 1
        return tok

    def _error(self, message: str) -> ParseError:
        tok = self._peek()
        return ParseError(message, tok.offset if tok is not None else self.end)

    def _expect_op(self, op: str) -> Token:
        tok = self._peek()
        if tok is None or tok.kind != "OP" or tok.text != op:
            raise self._error(f"expected {op!r}")
        self.pos += 1
        return tok

    def _expect_kw(self, kw: str) -> Token:
        tok = self._peek()
        if tok is None or tok.kind != "KEYWORD" or tok.text != kw:
            raise self._error(f"expected keyword {kw!r}")
        self.pos += 1
        return tok

    # -- statements ------------------------------------------------------

    def parse_program(self) -> list:
        stmts: list = []
        while self._peek() is not None:
            stmts.append(self._statement())
        return stmts

    def _statement(self) -> object:
        tok = self._peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.end)
        if tok.kind == "KEYWORD":
            if tok.text == "let":
                return self._let()
            if tok.text == "print":
                return self._print()
            if tok.text == "if":
                return self._if()
            if tok.text == "while":
                return self._while()
        if tok.kind == "OP" and tok.text == "{":
            return self._block()
        if tok.kind == "IDENT":
            return self._assign()
        raise self._error(f"unexpected token {tok.text!r}")

    def _block(self) -> list:
        self._expect_op("{")
        stmts: list = []
        while True:
            tok = self._peek()
            if tok is None:
                raise ParseError("unterminated block", self.end)
            if tok.kind == "OP" and tok.text == "}":
                self.pos += 1
                return stmts
            stmts.append(self._statement())

    def _let(self) -> Let:
        kw = self._expect_kw("let")
        name = self._advance()
        if name.kind != "IDENT":
            raise ParseError("expected identifier after 'let'", name.offset)
        self._expect_op("=")
        value = self._expression()
        self._expect_op(";")
        return Let(name.text, value, kw.offset)

    def _assign(self) -> Assign:
        name = self._advance()
        self._expect_op("=")
        value = self._expression()
        self._expect_op(";")
        return Assign(name.text, value, name.offset)

    def _print(self) -> Print:
        kw = self._expect_kw("print")
        value = self._expression()
        self._expect_op(";")
        return Print(value, kw.offset)

    def _if(self) -> If:
        kw = self._expect_kw("if")
        self._expect_op("(")
        cond = self._expression()
        self._expect_op(")")
        then = self._block()
        otherwise: list = []
        tok = self._peek()
        if tok is not None and tok.kind == "KEYWORD" and tok.text == "else":
            self.pos += 1
            nxt = self._peek()
            if nxt is not None and nxt.kind == "KEYWORD" and nxt.text == "if":
                otherwise = [self._if()]
            else:
                otherwise = self._block()
        return If(cond, then, otherwise, kw.offset)

    def _while(self) -> While:
        kw = self._expect_kw("while")
        self._expect_op("(")
        cond = self._expression()
        self._expect_op(")")
        body = self._block()
        return While(cond, body, kw.offset)

    # -- expressions -----------------------------------------------------

    def _expression(self) -> object:
        return self._or()

    def _or(self) -> object:
        node = self._and()
        while (tok := self._peek()) and tok.kind == "KEYWORD" and tok.text == "or":
            self.pos += 1
            node = BinOp("or", node, self._and(), tok.offset)
        return node

    def _and(self) -> object:
        node = self._not()
        while (tok := self._peek()) and tok.kind == "KEYWORD" and tok.text == "and":
            self.pos += 1
            node = BinOp("and", node, self._not(), tok.offset)
        return node

    def _not(self) -> object:
        tok = self._peek()
        if tok is not None and tok.kind == "KEYWORD" and tok.text == "not":
            self.pos += 1
            return UnaryOp("not", self._not(), tok.offset)
        return self._comparison()

    def _comparison(self) -> object:
        node = self._additive()
        tok = self._peek()
        if tok is not None and tok.kind == "OP" and tok.text in _COMPARISONS:
            self.pos += 1
            return BinOp(tok.text, node, self._additive(), tok.offset)
        return node

    def _additive(self) -> object:
        node = self._multiplicative()
        while (tok := self._peek()) and tok.kind == "OP" and tok.text in ("+", "-"):
            self.pos += 1
            node = BinOp(tok.text, node, self._multiplicative(), tok.offset)
        return node

    def _multiplicative(self) -> object:
        node = self._unary()
        while (tok := self._peek()) and tok.kind == "OP" and tok.text in ("*", "/", "%"):
            self.pos += 1
            node = BinOp(tok.text, node, self._unary(), tok.offset)
        return node

    def _unary(self) -> object:
        tok = self._peek()
        if tok is not None and tok.kind == "OP" and tok.text == "-":
            self.pos += 1
            return UnaryOp("-", self._unary(), tok.offset)
        return self._primary()

    def _primary(self) -> object:
        tok = self._advance()
        if tok.kind in ("INT", "FLOAT", "STRING"):
            return Literal(tok.value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text in ("true", "false"):
            return Literal(tok.text == "true", tok.offset)
        if tok.kind == "IDENT":
            return Var(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            node = self._expression()
            self._expect_op(")")
            return node
        raise ParseError(f"unexpected token {tok.text!r}", tok.offset)


def parse(src: str) -> object:
    """Parse ``src`` into an AST (a list of statement nodes)."""
    return _Parser(src).parse_program()

"""Compile the AST into a Program of stack-machine instructions."""

import dataclasses

from .errors import CompileError
from .parser import Assign, BinOp, If, Let, Literal, Print, UnaryOp, Var, While, parse


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str            # one of OPCODES
    arg: int | None    # None exactly when the opcode takes no argument


@dataclasses.dataclass
class Program:
    constants: list        # the constant pool
    names: list[str]       # variable names, slot order = declaration order
    instructions: list     # list[Instr]


_BIN_OPS = {
    "+": "ADD", "-": "SUB", "*": "MUL", "/": "DIV", "%": "MOD",
    "==": "EQ", "!=": "NE", "<": "LT", "<=": "LE", ">": "GT", ">=": "GE",
}


class _Compiler:
    """Single-pass code generator with a global name table."""

    def __init__(self) -> None:
        self.constants: list = []
        self._const_index: dict[tuple[type, object], int] = {}
        self.names: list[str] = []
        self._slots: dict[str, int] = {}
        self.code: list[Instr] = []

    def _emit(self, op: str, arg: int | None = None) -> int:
        self.code.append(Instr(op, arg))
        return len(self.code) - 1

    def _patch(self, at: int, target: int) -> None:
        self.code[at] = Instr(self.code[at].op, target)

    def _const(self, value: object) -> int:
        key = (type(value), value)
        if key not in self._const_index:
            self._const_index[key] = len(self.constants)
            self.constants.append(value)
        return self._const_index[key]

    def _slot(self, name: str, offset: int) -> int:
        if name not in self._slots:
            raise CompileError(f"name {name!r} is not declared")
        return self._slots[name]

    # -- statements ------------------------------------------------------

    def _stmt(self, node: object) -> None:
        if isinstance(node, Let):
            if node.name in self._slots:
                raise CompileError(f"name {node.name!r} declared twice")
            self._slots[node.name] = len(self.names)
            self.names.append(node.name)
            self._expr(node.value)
            self._emit("STORE", self._slots[node.name])
        elif isinstance(node, Assign):
            self._expr(node.value)
            self._emit("STORE", self._slot(node.name, node.offset))
        elif isinstance(node, Print):
            self._expr(node.value)
            self._emit("PRINT")
        elif isinstance(node, If):
            self._if(node)
        elif isinstance(node, While):
            self._while(node)
        elif isinstance(node, list):
            for sub in node:
                self._stmt(sub)
        else:  # pragma: no cover - defensive
            raise CompileError(f"unknown statement {node!r}")

    def _if(self, node: If) -> None:
        self._expr(node.cond)
        jf = self._emit("JUMP_IF_FALSE")
        self._stmt(node.then)
        if node.otherwise:
            j = self._emit("JUMP")
            self._patch(jf, len(self.code))
            self._stmt(node.otherwise)
            self._patch(j, len(self.code))
        else:
            self._patch(jf, len(self.code))

    def _while(self, node: While) -> None:
        top = len(self.code)
        self._expr(node.cond)
        jf = self._emit("JUMP_IF_FALSE")
        self._stmt(node.body)
        self._emit("JUMP", top)
        self._patch(jf, len(self.code))

    # -- expressions -----------------------------------------------------

    def _expr(self, node: object) -> None:
        if isinstance(node, Literal):
            self._emit("CONST", self._const(node.value))
        elif isinstance(node, Var):
            self._emit("LOAD", self._slot(node.name, node.offset))
        elif isinstance(node, UnaryOp):
            self._expr(node.operand)
            self._emit("NEG" if node.op == "-" else "NOT")
        elif isinstance(node, BinOp):
            if node.op == "and":
                self._logic(node, is_and=True)
            elif node.op == "or":
                self._logic(node, is_and=False)
            else:
                self._expr(node.left)
                self._expr(node.right)
                self._emit(_BIN_OPS[node.op])
        else:  # pragma: no cover - defensive
            raise CompileError(f"unknown expression {node!r}")

    def _logic(self, node: BinOp, *, is_and: bool) -> None:
        # JUMP_IF_FALSE type-checks each evaluated operand, preserving the
        # strict-bool rule for both sides of a short-circuit operator.
        true_k = self._const(True)
        false_k = self._const(False)
        self._expr(node.left)
        jf1 = self._emit("JUMP_IF_FALSE")
        if not is_and:
            self._emit("CONST", true_k)
            j_true = self._emit("JUMP")
            self._patch(jf1, len(self.code))
        self._expr(node.right)
        jf2 = self._emit("JUMP_IF_FALSE")
        self._emit("CONST", true_k)
        j_end = self._emit("JUMP")
        l_false = len(self.code)
        self._emit("CONST", false_k)
        self._patch(jf2, l_false)
        if is_and:
            self._patch(jf1, l_false)
        else:
            self._patch(j_true, len(self.code))
        self._patch(j_end, len(self.code))


def compile_source(src: str, *, optimize: bool = False) -> Program:
    """Compile ``src`` into a Program; optionally constant-fold the AST first."""
    tree = parse(src)
    if optimize:
        from .optimizer import fold_constants

        tree = fold_constants(tree)
    gen = _Compiler()
    gen._stmt(tree)
    gen._emit("HALT")
    return Program(gen.constants, gen.names, gen.code)

"""Stack-based virtual machine executing compiled Programs."""

from .compiler import Program
from .errors import StepLimitError, VMRuntimeError

_UNSET = object()  # marker for declared-but-never-assigned slots


def is_number(value: object) -> bool:
    """True for INT/FLOAT values; BOOL is not a number in this language."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def render(value: object) -> str:
    """Render a value the way ``print`` does (section 1 rule 9)."""
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def eval_binop(op: str, left: object, right: object) -> object:
    """Apply a binary operator under the section 1 run-time rules."""
    if op in ("==", "!="):
        eq = _equals(left, right)
        return eq if op == "==" else not eq
    if op in ("<", "<=", ">", ">="):
        return _compare(op, left, right)
    if op == "+" and isinstance(left, str) and isinstance(right, str):
        return left + right
    if op == "%":
        if not (type(left) is int and type(right) is int):
            raise VMRuntimeError("'%' requires two INT operands")
        if right == 0:
            raise VMRuntimeError("modulo by zero")
        return left % right
    if not (is_number(left) and is_number(right)):
        raise VMRuntimeError(f"operator {op!r} requires number operands")
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if right == 0:
        raise VMRuntimeError("division by zero")
    return left / right  # '/' always yields FLOAT


def _equals(left: object, right: object) -> bool:
    """Equality: INT/FLOAT compare numerically; BOOL differs from INT."""
    if is_number(left) and is_number(right):
        return left == right
    if type(left) is not type(right):
        return False
    return bool(left == right)


def _compare(op: str, left: object, right: object) -> bool:
    both_num = is_number(left) and is_number(right)
    both_str = isinstance(left, str) and isinstance(right, str)
    if not (both_num or both_str):
        raise VMRuntimeError(f"operator {op!r} requires two numbers or two strings")
    if op == "<":
        return bool(left < right)
    if op == "<=":
        return bool(left <= right)
    if op == ">":
        return bool(left > right)
    return bool(left >= right)


def eval_neg(value: object) -> object:
    """Unary minus requires a number."""
    if not is_number(value):
        raise VMRuntimeError("unary '-' requires a number")
    return -value


def eval_not(value: object) -> bool:
    """Logical not requires a BOOL."""
    if not isinstance(value, bool):
        raise VMRuntimeError("'not' requires a BOOL operand")
    return not value


def _require_bool(value: object, what: str) -> bool:
    if not isinstance(value, bool):
        raise VMRuntimeError(f"{what} requires a BOOL operand")
    return value


def _step(program: Program, stack: list, slots: list, ip: int, out: list[str]) -> int:
    """Execute one instruction; return the next instruction pointer."""
    ins = program.instructions[ip]
    op = ins.op
    if op == "HALT":
        return -1
    if op == "CONST":
        stack.append(program.constants[ins.arg])
    elif op == "LOAD":
        value = slots[ins.arg]
        if value is _UNSET:
            raise VMRuntimeError(
                f"variable {program.names[ins.arg]!r} was never assigned"
            )
        stack.append(value)
    elif op == "STORE":
        slots[ins.arg] = stack.pop()
    elif op == "PRINT":
        out.append(render(stack.pop()))
    elif op == "POP":
        stack.pop()
    elif op == "NEG":
        stack.append(eval_neg(stack.pop()))
    elif op == "NOT":
        stack.append(eval_not(stack.pop()))
    elif op == "JUMP":
        return int(ins.arg)
    elif op == "JUMP_IF_FALSE":
        if not _require_bool(stack.pop(), "JUMP_IF_FALSE"):
            return int(ins.arg)
    else:
        right = stack.pop()
        left = stack.pop()
        stack.append(eval_binop(op, left, right))
    return ip + 1


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    """Run ``program`` and return the printed lines in order."""
    if isinstance(step_limit, bool) or not isinstance(step_limit, int) or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    stack: list = []
    slots: list = [_UNSET] * len(program.names)
    out: list[str] = []
    ip = 0
    steps = 0
    while ip >= 0:
        steps += 1
        if steps > step_limit:
            raise StepLimitError(f"step limit of {step_limit} exceeded")
        ip = _step(program, stack, slots, ip, out)
    return out

"""Constant folding over the AST; never changes observable behaviour."""

import dataclasses

from .errors import VMRuntimeError
from .parser import Assign, BinOp, If, Let, Literal, Print, UnaryOp, While
from .vm import eval_binop, eval_neg, eval_not


def _fold_expr(node: object) -> object:
    """Fold an expression bottom-up; returns a (possibly new) node."""
    if isinstance(node, (Literal,)):
        return node
    if isinstance(node, UnaryOp):
        return _fold_unary(node)
    if isinstance(node, BinOp):
        return _fold_binary(node)
    return node


def _fold_unary(node: UnaryOp) -> object:
    operand = _fold_expr(node.operand)
    if isinstance(operand, Literal):
        try:
            fn = eval_neg if node.op == "-" else eval_not
            return Literal(fn(operand.value), node.offset)
        except VMRuntimeError:
            pass  # would fail at run time; leave unfolded
    return dataclasses.replace(node, operand=operand)


def _fold_binary(node: BinOp) -> object:
    left = _fold_expr(node.left)
    right = _fold_expr(node.right)
    if node.op in ("and", "or"):
        return _fold_logic(node, left, right)
    if isinstance(left, Literal) and isinstance(right, Literal):
        try:
            return Literal(eval_binop(node.op, left.value, right.value), node.offset)
        except VMRuntimeError:
            pass  # e.g. 1 / 0 or "a" + 1: must still fail at run time
    return dataclasses.replace(node, left=left, right=right)


def _fold_logic(node: BinOp, left: object, right: object) -> object:
    """Fold and/or only where the run-time BOOL checks are preserved."""
    if isinstance(left, Literal) and isinstance(right, Literal):
        if isinstance(left.value, bool) and isinstance(right.value, bool):
            value = (left.value and right.value) if node.op == "and" else (
                left.value or right.value
            )
            return Literal(bool(value), node.offset)
    if isinstance(left, Literal) and isinstance(left.value, bool):
        # The skipped side is never evaluated, so dropping it is safe; the
        # opposite direction (true and X / false or X) must keep X's check.
        if node.op == "and" and left.value is False:
            return Literal(False, node.offset)
        if node.op == "or" and left.value is True:
            return Literal(True, node.offset)
    return dataclasses.replace(node, left=left, right=right)


def _fold_stmt(node: object) -> object:
    """Fold every expression inside a statement, recursing into blocks."""
    if isinstance(node, (Let, Assign, Print)):
        return dataclasses.replace(node, value=_fold_expr(node.value))
    if isinstance(node, If):
        return dataclasses.replace(
            node,
            cond=_fold_expr(node.cond),
            then=[_fold_stmt(s) for s in node.then],
            otherwise=[_fold_stmt(s) for s in node.otherwise],
        )
    if isinstance(node, While):
        return dataclasses.replace(
            node, cond=_fold_expr(node.cond),
            body=[_fold_stmt(s) for s in node.body],
        )
    return node


def fold_constants(node: object) -> object:
    """Fold constants in an AST (a statement list); returns a new AST."""
    return [_fold_stmt(stmt) for stmt in node]

"""Binary codec for Programs: magic + version + payload + CRC32 checksum."""

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import ARG_OPS, OPCODE_NUMBERS, OPCODES

MAGIC = b"MVM1"
VERSION = 1
_NO_ARG = 0xFFFFFFFF

_TAG_INT = 0x01
_TAG_FLOAT = 0x02
_TAG_STRING = 0x03
_TAG_BOOL = 0x04


def _dump_constant(value: object) -> bytes:
    if isinstance(value, bool):
        return bytes([_TAG_BOOL, 1 if value else 0])
    if isinstance(value, int):
        if not (-(2 ** 63) <= value < 2 ** 63):
            raise SerializationError("INT constant out of signed 64-bit range")
        return bytes([_TAG_INT]) + struct.pack(">q", value)
    if isinstance(value, float):
        return bytes([_TAG_FLOAT]) + struct.pack(">d", value)
    if isinstance(value, str):
        raw = value.encode("utf-8")
        return bytes([_TAG_STRING]) + struct.pack(">I", len(raw)) + raw
    raise SerializationError(f"unsupported constant type {type(value).__name__}")


def dumps(program: Program) -> bytes:
    """Serialize ``program`` deterministically to the MVM1 binary format."""
    body = bytearray([VERSION])
    body += struct.pack(">H", len(program.names))
    for name in program.names:
        raw = name.encode("utf-8")
        body += struct.pack(">H", len(raw)) + raw
    body += struct.pack(">H", len(program.constants))
    for value in program.constants:
        body += _dump_constant(value)
    body += struct.pack(">I", len(program.instructions))
    for ins in program.instructions:
        if ins.op in ARG_OPS:
            if ins.arg is None:
                raise SerializationError(f"{ins.op} requires an argument")
            arg = ins.arg
        else:
            if ins.arg is not None:
                raise SerializationError(f"{ins.op} takes no argument")
            arg = _NO_ARG
        body += bytes([OPCODE_NUMBERS[ins.op]]) + struct.pack(">I", arg)
    checksum = zlib.crc32(bytes(body)) & 0xFFFFFFFF
    return MAGIC + bytes(body) + struct.pack(">I", checksum)


class _Reader:
    """Bounds-checked big-endian cursor over the checksummed body."""

    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def read(self, n: int) -> bytes:
        if self.pos + n > len(self.data):
            raise SerializationError("truncated data")
        chunk = self.data[self.pos:self.pos + n]
        self.pos += n
        return chunk

    def u8(self) -> int:
        return self.read(1)[0]

    def u16(self) -> int:
        return struct.unpack(">H", self.read(2))[0]

    def u32(self) -> int:
        return struct.unpack(">I", self.read(4))[0]


def _load_constant(reader: _Reader) -> object:
    tag = reader.u8()
    if tag == _TAG_INT:
        return struct.unpack(">q", reader.read(8))[0]
    if tag == _TAG_FLOAT:
        return struct.unpack(">d", reader.read(8))[0]
    if tag == _TAG_STRING:
        return reader.read(reader.u32()).decode("utf-8")
    if tag == _TAG_BOOL:
        value = reader.u8()
        if value not in (0, 1):
            raise SerializationError(f"invalid BOOL payload {value}")
        return value == 1
    raise SerializationError(f"unknown constant tag 0x{tag:02X}")


def _load_instruction(reader: _Reader) -> Instr:
    number = reader.u8()
    if not (1 <= number <= len(OPCODES)):
        raise SerializationError(f"unknown opcode number {number}")
    op = OPCODES[number - 1]
    arg = reader.u32()
    if op in ARG_OPS:
        if arg == _NO_ARG:
            raise SerializationError(f"{op} is missing its argument")
        return Instr(op, arg)
    if arg != _NO_ARG:
        raise SerializationError(f"{op} must not carry an argument")
    return Instr(op, None)


def loads(data: bytes) -> Program:
    """Decode the MVM1 binary format, validating the checksum first."""
    if len(data) < 8 or not data.startswith(MAGIC):
        raise SerializationError("bad magic")
    body, raw_crc = data[4:-4], struct.unpack(">I", data[-4:])[0]
    if zlib.crc32(body) & 0xFFFFFFFF != raw_crc:
        raise SerializationError("checksum mismatch")
    reader = _Reader(body)
    if reader.u8() != VERSION:
        raise SerializationError("unsupported version")
    names = [reader.read(reader.u16()).decode("utf-8") for _ in range(reader.u16())]
    constants = [_load_constant(reader) for _ in range(reader.u16())]
    instructions = [_load_instruction(reader) for _ in range(reader.u32())]
    if reader.pos != len(body):
        raise SerializationError("trailing bytes after final section")
    return Program(constants, names, instructions)

"""Human-readable rendering of compiled Programs."""

from .compiler import Program


def _render_constant(value: object) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        escaped = (
            value.replace("\\", "\\\\")
            .replace("\n", "\\n")
            .replace("\t", "\\t")
            .replace('"', '\\"')
        )
        return f'"{escaped}"'
    return str(value)


def disassemble(program: Program) -> str:
    """Return one line per instruction in the canonical assembly format."""
    lines: list[str] = []
    for index, ins in enumerate(program.instructions):
        line = f"{index:04d} {ins.op}"
        if ins.arg is not None:
            line += f" {ins.arg}"
        if ins.op == "CONST":
            line += f"  ; {_render_constant(program.constants[ins.arg])}"
        lines.append(line + "\n")
    return "".join(lines)

